import numpy as np
x = np.array([0.,1.,2.,3.,20.])
tree = (10., (1.5, (.5,None,None), (2.5,None,None)), None)
def depth(value,node):
    if node is None:
        return 0
    threshold,left,right = node
    return 1+depth(value,left if value<threshold else right)
print([depth(value,tree) for value in x])

