import hashlib
import json
a = {"weights":[2.,-1.],"schema":"v1"}
b = {"schema":"v1","weights":[2.,-1.]}
c = {"schema":"v1","weights":[2.,-2.]}
def digest(value):
    payload = json.dumps(value,sort_keys=True,separators=(",",":"))
    return hashlib.sha256(payload.encode()).hexdigest()
print(digest(a)==digest(b))
print(digest(a)==digest(c))

